// TradeZoro — indicator pages (/indicators hub + /indicators/<slug>), generated by tools/gen-indicator-pages.js.
//   hub: search + group chips (no reload; ?g=<group> / #<group> deep links)
//   page: "Add to chart" -> /charts?ind=<key> (assets/chart-indicator-window.js adds it); signed-out visitors go to
//         sign-up first and come back (auth.js reads sessionStorage stryker_return_to after sign-up)
//         "Favourite" -> the Indicators window's own favourites: students/{uid}/chartFavorites/<key with : -> _>
//         ({ key, name, at }), or localStorage stryker_chart_favs when signed out (same as the chart).
// Depends on: assets/auth.js (auth, firebase compat) when present. No other imports.
(function () {
  'use strict';
  var FAV_LS = 'stryker_chart_favs';

  // ---------------------------------------------------------------- hub
  var q = document.getElementById('ixh-q');
  if (q) {
    var chips = [].slice.call(document.querySelectorAll('.ixh-chipb'));
    var cards = [].slice.call(document.querySelectorAll('.ixh-card'));
    var secs = [].slice.call(document.querySelectorAll('.ixh-sec[data-sec]'));
    var empty = document.getElementById('ixh-empty');
    var group = '';
    var apply = function () {
      var t = q.value.trim().toLowerCase(), n = 0;
      cards.forEach(function (c) {
        var on = (!group || c.getAttribute('data-group') === group) && (!t || c.getAttribute('data-q').indexOf(t) !== -1);
        c.hidden = !on; if (on) n++;
      });
      secs.forEach(function (s) { s.hidden = !s.querySelector('.ixh-card:not([hidden])'); });
      chips.forEach(function (c) { c.setAttribute('aria-pressed', String(c.getAttribute('data-g') === group)); });
      if (empty) empty.hidden = n > 0;
    };
    var setGroup = function (g, push) {
      group = g || '';
      apply();
      if (push) { try { history.replaceState(null, '', location.pathname + (group ? '#' + group : '')); } catch (e) {} }
    };
    chips.forEach(function (c) { c.addEventListener('click', function () { setGroup(c.getAttribute('data-g'), true); window.scrollTo({ top: 0 }); }); });
    q.addEventListener('input', apply);
    var h = (location.hash || '').slice(1);
    if (h && chips.some(function (c) { return c.getAttribute('data-g') === h; })) setGroup(h, false);
  }

  // ---------------------------------------------------------------- page
  var user = function () { try { return (typeof auth !== 'undefined' && auth && auth.currentUser) || null; } catch (e) { return null; } };
  var authReady = new Promise(function (res) {
    try {
      if (typeof auth === 'undefined' || !auth) return res(null);
      var off = auth.onAuthStateChanged(function (u) { off && off(); res(u); });
      setTimeout(function () { res(user()); }, 4000);
    } catch (e) { res(null); }
  });

  [].slice.call(document.querySelectorAll('[data-ind-add]')).forEach(function (a) {
    a.addEventListener('click', function (ev) {
      if (user()) return;   // signed in: the link opens the chart with ?ind=
      ev.preventDefault();
      authReady.then(function (u) {
        if (u) { location.href = a.getAttribute('href'); return; }
        try { sessionStorage.setItem('stryker_return_to', a.getAttribute('href')); } catch (e) {}
        location.href = '/signup?utm_source=indicators&utm_medium=page&utm_campaign=add-to-chart';
      });
    });
  });

  var fav = document.querySelector('[data-ind-fav]');
  if (!fav) return;
  var key = fav.getAttribute('data-ind-fav'), name = fav.getAttribute('data-ind-name') || key;
  var docId = key.replace(/:/g, '_');
  var col = function (u) { return firebase.firestore().collection('students').doc(u.uid).collection('chartFavorites'); };
  var lsGet = function () { try { return JSON.parse(localStorage.getItem(FAV_LS) || '[]') || []; } catch (e) { return []; } };
  var show = function (on) {
    fav.setAttribute('aria-pressed', String(on));
    fav.querySelector('span').textContent = on ? 'Favourited' : 'Favourite';
    fav.title = on ? 'Remove from your chart favourites' : 'Add to your chart favourites (the star list in the Indicators window)';
  };
  var state = false;
  authReady.then(function (u) {
    if (u) return col(u).doc(docId).get().then(function (d) { state = d.exists; show(state); }).catch(function () { show(false); });
    state = lsGet().some(function (x) { return x && x.key === key; }); show(state);
  });
  fav.addEventListener('click', function () {
    var on = !state, u = user();
    fav.classList.add('is-busy');
    var done = function () { state = on; show(on); fav.classList.remove('is-busy');
      if (typeof showToast === 'function') showToast('success', on ? 'Added to your chart favourites.' : 'Removed from your chart favourites.'); };
    var fail = function (e) { fav.classList.remove('is-busy'); console.warn('TradeZoro: favourite', e);
      if (typeof showToast === 'function') showToast('error', 'Could not save the favourite.'); };
    if (u) {
      var ref = col(u).doc(docId);
      (on ? ref.set({ key: key, name: name.slice(0, 80), at: firebase.firestore.FieldValue.serverTimestamp() }) : ref.delete()).then(done, fail);
    } else {
      try {
        var a = lsGet().filter(function (x) { return x && x.key !== key; });
        if (on) a.push({ key: key, name: name.slice(0, 80) });
        localStorage.setItem(FAV_LS, JSON.stringify(a));
        done();
      } catch (e) { fail(e); }
    }
  });
})();
